 public void run(){try{boolean tls=url.startsWith("wss://");String rest=url.replaceFirst("^wss?://","");int slash=rest.indexOf('/');String path=slash<0?"/":rest.substring(slash);if(slash>=0)rest=rest.substring(0,slash);String host=rest;int port=tls?443:80,colon=rest.lastIndexOf(':');if(colon>0){host=rest.substring(0,colon);port=Integer.parseInt(rest.substring(colon+1));}if(tls){socket=(SSLSocket)SSLSocketFactory.getDefault().createSocket(host,port);SSLParameters p=((SSLSocket)socket).getSSLParameters();if(!host.matches("\\d{1,3}(\\.\\d{1,3}){3}"))p.setServerNames(java.util.Collections.singletonList(new SNIHostName(host)));p.setEndpointIdentificationAlgorithm("HTTPS");((SSLSocket)socket).setSSLParameters(p);((SSLSocket)socket).startHandshake();}else socket=new Socket(host,port);socket.setTcpNoDelay(true);in=socket.getInputStream();out=socket.getOutputStream();byte[] key=new byte[16];new SecureRandom().nextBytes(key);String k=android.util.Base64.encodeToString(key,android.util.Base64.NO_WRAP);out.write(("GET "+path+" HTTP/1.1\r\nHost: "+host+":"+port+"\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: "+k+"\r\nSec-WebSocket-Version: 13\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.flush();ByteArrayOutputStream h=new ByteArrayOutputStream();int prev=0,b;while((b=in.read())!=-1){h.write(b);if(prev==13&&b==10&&h.toString("UTF-8").endsWith("\r\n\r\n"))break;prev=b;}if(!h.toString("UTF-8").contains("101"))throw new IOException("Handshake failed");Thread writer=new Thread(()->{while(running)try{String s=queue.poll(200,TimeUnit.MILLISECONDS);if(s!=null)write(s);}catch(Exception e){close();}});writer.setDaemon(true);writer.start();while(running){String s=read();if(s==null)break;receive.accept(s);}}catch(Exception ignored){}finally{close();}}
 void write(String s)throws IOException{byte[] d=s.getBytes(StandardCharsets.UTF_8),m=new byte[4];new SecureRandom().nextBytes(m);ByteArrayOutputStream f=new ByteArrayOutputStream();f.write(129);if(d.length<126)f.write(128|d.length);else{f.write(254);f.write(d.length>>8);f.write(d.length);}f.write(m);for(int i=0;i<d.length;i++)f.write(d[i]^m[i%4]);synchronized(out){out.write(f.toByteArray());out.flush();}}
 String read()throws IOException{int a=in.read(),b=in.read();if(a<0||b<0)return null;int op=a&15;long n=b&127;if(n==126)n=((in.read()&255)<<8)|(in.read()&255);else if(n==127)throw new IOException("Large frame");boolean masked=(b&128)!=0;byte[] m=masked?new byte[4]:null;if(masked)for(int i=0;i<4;i++)m[i]=(byte)in.read();byte[] d=new byte[(int)n];int off=0;while(off<d.length){int z=in.read(d,off,d.length-off);if(z<0)return null;off+=z;}if(masked)for(int i=0;i<d.length;i++)d[i]^=m[i%4];if(op==8)return null;if(op==9){pong(d);return read();}return op==1?new String(d,StandardCharsets.UTF_8):read();}
 void pong(byte[] d)throws IOException{byte[] m=new byte[4];new SecureRandom().nextBytes(m);ByteArrayOutputStream f=new ByteArrayOutputStream();f.write(138);f.write(128|d.length);f.write(m);for(int i=0;i<d.length;i++)f.write(d[i]^m[i%4]);synchronized(out){out.write(f.toByteArray());out.flush();}}
